afterExample:
package test;

import org.eclipse.search.ui.ISearchScope;
import org.eclipse.search.internal.ui.text.TextSearchPageInput;

class DummyData {
    String textPattern = "pattern";
    boolean isCaseSensitive = false;
    boolean isRegExSearch = true;
    boolean isWholeWord = true;
}

public class TestClass {
    public void someMethod(DummyData data, ISearchScope s) {
        // Transformed line, whole word is now false due to regex being true
        TextSearchPageInput input = new TextSearchPageInput(data.textPattern, data.isCaseSensitive, data.isRegExSearch, data.isWholeWord && !data.isRegExSearch, s);
    }
}

